import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ViewReports({ subject }) {
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);

  // 🟢 ටීචර්ගේ සබ්ජෙක්ට් එක (Grade 9 - IT වැනි) ඩේටාබේස් එකේ (ICT) නමට ගැලපෙන සේ සකස් කිරීම
  const fullSubject = subject || 'ICT';
  const subjectParts = fullSubject.split(' - ');
  let teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;
  if (teachingSubject === 'IT' || teachingSubject === 'Information Technology') {
    teachingSubject = 'ICT';
  }

  // 🟢 ඩේටාබේස් එකේ student_results ටේබල් එකෙන් දත්ත කියවා ගැනීම
  useEffect(() => {
    axios.get('http://localhost:8081/api/student-results')
      .then(res => {
        setReports(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching reports:", err);
        setLoading(false);
      });
  }, []);

  // 🟢 දැනට ලොග් වෙලා ඉන්න ටීචර්ගේ විෂයට අදාළ ලකුණු විතරක් ෆිල්ටර් කර ගැනීම
  const filteredReports = reports.filter(r => r.subject_name === teachingSubject);

  // 🟢 Native Browser Print හරහා ලස්සනට PDF එකක් විදියට ඩවුන්ලෝඩ් කිරීමේ ෆන්ක්ෂන් එක
  const handleDownloadPDF = () => {
    const printContent = document.getElementById('report-area').innerHTML;
    const printWindow = window.open('', '', 'height=600,width=800');
    
    printWindow.document.write('<html><head><title>Student Performance Report</title>');
    printWindow.document.write('<style>');
    printWindow.document.write('body { font-family: sans-serif; padding: 30px; color: #1e293b; }');
    printWindow.document.write('h2 { color: #0f172a; margin-bottom: 5px; }');
    printWindow.document.write('p { color: #64748b; font-size: 14px; margin-top: 0; }');
    printWindow.document.write('table { width: 100%; border-collapse: collapse; margin-top: 25px; }');
    printWindow.document.write('th, td { border: 1px solid #e2e8f0; padding: 14px 12px; text-align: left; font-size: 14px; }');
    printWindow.document.write('th { background-color: #f8fafc; color: #475569; font-weight: bold; }');
    printWindow.document.write('tr { border-bottom: 1px solid #f1f5f9; }');
    printWindow.document.write('</style></head><body>');
    printWindow.document.write(printContent);
    printWindow.document.write('</body></html>');
    
    printWindow.document.close();
    printWindow.print();
  };

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      
      {/* ප්‍රධාන කාඩ් එක */}
      <div style={styles.card}>
        
        {/* ඉහළ මාතෘකාව සහ ඩවුන්ලෝඩ් බටන් එක */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px' }}>
          <div>
            <h2 style={{ color: '#1e293b', margin: 0, fontSize: '22px' }}>📊 Student Performance</h2>
            <p style={{ color: '#64748b', margin: '5px 0 0 0', fontSize: '14px', fontWeight: '500' }}>
              Grade 9 {teachingSubject} Exam Summary List
            </p>
          </div>
          <button onClick={handleDownloadPDF} style={styles.downloadBtn}>
            Download Full Report
          </button>
        </div>

        {/* 🖨️ PDF එකට ප්‍රින්ට් වෙන ප්‍රධාන කොටස */}
        <div id="report-area">
          <table style={styles.table}>
            <thead>
              <tr style={styles.thRow}>
                <th style={styles.th}>Student Name</th>
                <th style={styles.th}>Quiz Paper Type</th>
                <th style={styles.th}>Marks Scored</th>
                <th style={styles.th}>Grade Status</th>
              </tr>
            </thead>
            <tbody>
              {filteredReports.map((report) => (
                <tr key={report.id} style={styles.tr}>
                  <td style={styles.td}>{report.student_name}</td>
                  <td style={styles.td}>{report.quiz_title}</td>
                  <td style={styles.td}>{report.marks_obtained} / {report.total_marks}</td>
                  <td style={styles.td}>
                    <span style={getStatusStyle(report.status)}>{report.status}</span>
                  </td>
                </tr>
              ))}
              
              {filteredReports.length === 0 && !loading && (
                <tr>
                  <td colSpan="4" style={{ textAlign: 'center', padding: '30px', color: '#94a3b8', fontSize: '14px' }}>
                    No student reports available for {teachingSubject} yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
}

// Status එක අනුව පාටවල් ඔටෝම මාරු වෙන ක්‍රමය (Excellent -> Green, Pass -> Blue, Average -> Orange)
const getStatusStyle = (status) => {
  if (!status) return {};
  const lower = status.toLowerCase();
  if (lower.includes('excellent')) return { color: '#16a34a', fontWeight: 'bold' };
  if (lower.includes('pass')) return { color: '#2563eb', fontWeight: 'bold' };
  return { color: '#d97706', fontWeight: 'bold' };
};

const styles = {
  card: {
    backgroundColor: '#ffffff',
    padding: '30px',
    borderRadius: '12px',
    border: '1px solid #e2e8f0',
    boxShadow: '0 4px 12px rgba(0,0,0,0.01)'
  },
  downloadBtn: {
    backgroundColor: '#0f172a',
    color: '#ffffff',
    border: 'none',
    padding: '10px 20px',
    borderRadius: '6px',
    cursor: 'pointer',
    fontWeight: 'bold',
    fontSize: '13px',
    transition: 'background 0.2s'
  },
  table: {
    width: '100%',
    borderCollapse: 'collapse',
    marginTop: '10px'
  },
  thRow: {
    borderBottom: '2px solid #cbd5e1'
  },
  th: {
    textAlign: 'left',
    padding: '14px 12px',
    color: '#475569',
    fontSize: '14px',
    fontWeight: '600',
    backgroundColor: '#f8fafc'
  },
  tr: {
    borderBottom: '1px solid #f1f5f9'
  },
  td: {
    padding: '14px 12px',
    color: '#334155',
    fontSize: '14px'
  }
};
